<?php require __DIR__.'/config.php'; require_admin(); $pdo=db(); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='toggle_user'){$pdo->prepare('UPDATE users SET is_active=1-is_active WHERE id=? AND role<>\'admin\'')->execute([(int)$_POST['id']]);}elseif($action==='plan'){$pdo->prepare('UPDATE users SET plan_id=? WHERE id=?')->execute([(int)$_POST['plan_id'],(int)$_POST['id']]);}header('Location: admin.php');exit;}$stats=['users'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='user'")->fetchColumn(),'active'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='user' AND is_active=1")->fetchColumn(),'links'=>(int)$pdo->query('SELECT COUNT(*) FROM links')->fetchColumn(),'revenue'=>(float)$pdo->query("SELECT COALESCE(SUM(amount_iqd),0) FROM payments WHERE status='paid'")->fetchColumn()];$users=$pdo->query('SELECT u.id,u.name,u.username,u.email,u.phone,u.is_active,u.created_at,p.name plan_name,u.plan_id FROM users u LEFT JOIN plans p ON p.id=u.plan_id ORDER BY u.id DESC LIMIT 100')->fetchAll();$plans=$pdo->query('SELECT id,name,monthly_price_iqd FROM plans WHERE is_active=1 ORDER BY monthly_price_iqd')->fetchAll();?><!doctype html><html lang="<?=lang()?>" dir="<?=dir_attr()?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin · <?=APP_NAME?></title><link rel="stylesheet" href="assets/style.css"></head><body><div class="layout"><aside class="sidebar"><div class="brand">Link<span>iraq</span></div><a class="side-link" href="dashboard.php">لوحة المستخدم</a><a class="side-link active" href="admin.php">لوحة المدير</a><a class="side-link" href="index.php">الموقع</a><a class="side-link" href="logout.php">خروج</a></aside><main class="main"><div class="topbar"><div><h1 style="margin:0">لوحة المدير</h1><div class="muted">إدارة الحسابات والخطط ومؤشرات المنصة</div></div></div><section class="stats"><div class="card stat"><span class="muted">المستخدمون</span><strong><?=number_format($stats['users'])?></strong></div><div class="card stat"><span class="muted">النشطون</span><strong><?=number_format($stats['active'])?></strong></div><div class="card stat"><span class="muted">الروابط</span><strong><?=number_format($stats['links'])?></strong></div><div class="card stat"><span class="muted">الإيراد المدفوع</span><strong><?=number_format($stats['revenue'])?> د.ع</strong></div></section><section class="card" style="margin-top:22px"><h2>المستخدمون</h2><div class="table-wrap"><table class="table"><thead><tr><th>المستخدم</th><th>التواصل</th><th>الخطة</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=e($u['name'])?></strong><div class="muted">@<?=e($u['username'])?></div></td><td><?=e($u['email']?:$u['phone'])?></td><td><form method="post" style="display:flex;gap:7px"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="plan"><input type="hidden" name="id" value="<?=$u['id']?>"><select name="plan_id" style="padding:8px;border-radius:10px;border:1px solid #ddd"><?php foreach($plans as $p):?><option value="<?=$p['id']?>" <?=$u['plan_id']==$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select><button class="btn">حفظ</button></form></td><td><?=$u['is_active']?'نشط':'موقوف'?></td><td><?php if($u['username']!==user()['username']):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="toggle_user"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn"><?=$u['is_active']?'إيقاف':'تفعيل'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></main></div></body></html>